package com.ticketflow.payments
import org.jetbrains.exposed.sql.*
import org.jetbrains.exposed.sql.transactions.transaction
import java.math.BigDecimal
import java.time.OffsetDateTime
import java.util.UUID
class PaymentRepository{fun create(r:CreatePaymentRequest):PaymentResponse=transaction{findByKeyInternal(r.idempotencyKey)?.let{return@transaction it};val id=UUID.randomUUID();val now=OffsetDateTime.now();PaymentsTable.insert{it[PaymentsTable.id]=id;it[orderId]=UUID.fromString(r.orderId);it[userId]=UUID.fromString(r.userId);it[amount]=BigDecimal(r.amount);it[currency]=r.currency.uppercase();it[status]=PaymentStatus.SUCCEEDED.name;it[idempotencyKey]=r.idempotencyKey;it[createdAt]=now;it[updatedAt]=now};findByIdInternal(id)!!};fun findById(id:UUID)=transaction{findByIdInternal(id)};fun findByOrder(id:UUID)=transaction{PaymentsTable.selectAll().where{PaymentsTable.orderId eq id}.map{it.response()}};private fun findByKeyInternal(k:String)=PaymentsTable.selectAll().where{PaymentsTable.idempotencyKey eq k}.singleOrNull()?.response();private fun findByIdInternal(id:UUID)=PaymentsTable.selectAll().where{PaymentsTable.id eq id}.singleOrNull()?.response();private fun ResultRow.response()=PaymentResponse(this[PaymentsTable.id].toString(),this[PaymentsTable.orderId].toString(),this[PaymentsTable.userId].toString(),this[PaymentsTable.amount].toPlainString(),this[PaymentsTable.currency],PaymentStatus.valueOf(this[PaymentsTable.status]),this[PaymentsTable.idempotencyKey],this[PaymentsTable.createdAt].toString(),this[PaymentsTable.updatedAt].toString())}